-- VibeMitra core schema, version 1.
-- Applied by Flyway from backend startup (see backend/src/main/resources/application.yml).
-- IDs are generated by the application (UUID v4); timestamps are timestamptz.

-- ---------------------------------------------------------------------------
-- Accounts
-- ---------------------------------------------------------------------------
CREATE TABLE users (
    id              uuid PRIMARY KEY,
    email           varchar(255) NOT NULL,
    password_hash   varchar(100) NOT NULL,
    display_name    varchar(60)  NOT NULL,
    date_of_birth   date         NOT NULL,
    -- Launch scope is Delhi NCR. Extend this list (or move to a cities table) for new regions.
    city            varchar(20)  NOT NULL
                    CHECK (city IN ('DELHI', 'NOIDA', 'GHAZIABAD', 'GURUGRAM', 'FARIDABAD')),
    status          varchar(20)  NOT NULL DEFAULT 'ACTIVE'
                    CHECK (status IN ('ACTIVE', 'SUSPENDED', 'DELETED')),
    created_at      timestamptz  NOT NULL DEFAULT now(),
    updated_at      timestamptz  NOT NULL DEFAULT now(),
    deleted_at      timestamptz
);

-- Emails are stored lower-cased by the application; the unique index is the real guarantee.
CREATE UNIQUE INDEX ux_users_email ON users (email);
CREATE INDEX ix_users_city_status ON users (city, status);

-- ---------------------------------------------------------------------------
-- Profiles and preferences
-- ---------------------------------------------------------------------------
CREATE TABLE profiles (
    user_id              uuid PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    bio                  varchar(500),
    relationship_intent  varchar(30)
                         CHECK (relationship_intent IN
                                ('DATING', 'FRIENDSHIP', 'SERIOUS_RELATIONSHIP',
                                 'ROOMMATE', 'ACTIVITY_PARTNER', 'WEEKEND_PARTNER', 'TRAVEL_PARTNER')),
    preferred_language   varchar(10),
    updated_at           timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE interests (
    id        bigserial PRIMARY KEY,
    code      varchar(50) NOT NULL UNIQUE,
    label     varchar(80) NOT NULL,
    category  varchar(30) NOT NULL
);

CREATE TABLE user_interests (
    user_id     uuid   NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    interest_id bigint NOT NULL REFERENCES interests (id) ON DELETE CASCADE,
    PRIMARY KEY (user_id, interest_id)
);

-- ---------------------------------------------------------------------------
-- Matching, messaging and safety
-- ---------------------------------------------------------------------------
CREATE TABLE matches (
    id           uuid PRIMARY KEY,
    user_low_id  uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    user_high_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    status       varchar(20) NOT NULL DEFAULT 'PENDING'
                 CHECK (status IN ('PENDING', 'MATCHED', 'CLOSED')),
    -- Canonical ordering so each pair exists exactly once.
    CONSTRAINT ck_matches_order CHECK (user_low_id < user_high_id),
    CONSTRAINT ux_matches_pair UNIQUE (user_low_id, user_high_id),
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE messages (
    id         uuid PRIMARY KEY,
    match_id   uuid NOT NULL REFERENCES matches (id) ON DELETE CASCADE,
    sender_id  uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    body       varchar(2000) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_messages_match_created ON messages (match_id, created_at);

CREATE TABLE blocks (
    blocker_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    blocked_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (blocker_id, blocked_id),
    CONSTRAINT ck_blocks_not_self CHECK (blocker_id <> blocked_id)
);
CREATE INDEX ix_blocks_blocked ON blocks (blocked_id);

CREATE TABLE reports (
    id          uuid PRIMARY KEY,
    reporter_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    reported_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    reason      varchar(40)  NOT NULL,
    details     varchar(1000),
    status      varchar(20)  NOT NULL DEFAULT 'OPEN'
                CHECK (status IN ('OPEN', 'REVIEWING', 'ACTIONED', 'DISMISSED')),
    created_at  timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT ck_reports_not_self CHECK (reporter_id <> reported_id)
);
CREATE INDEX ix_reports_status ON reports (status, created_at);

-- ---------------------------------------------------------------------------
-- Subscriptions (entitlements are always verified server-side)
-- ---------------------------------------------------------------------------
CREATE TABLE subscriptions (
    id                  uuid PRIMARY KEY,
    user_id             uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    provider            varchar(20) NOT NULL CHECK (provider IN ('GOOGLE_PLAY', 'RAZORPAY', 'CASHFREE')),
    plan                varchar(20) NOT NULL CHECK (plan IN ('PREMIUM', 'PREMIUM_PLUS')),
    status              varchar(20) NOT NULL
                        CHECK (status IN ('ACTIVE', 'GRACE', 'ON_HOLD', 'CANCELLED', 'EXPIRED')),
    external_reference  varchar(255) NOT NULL UNIQUE,
    current_period_end  timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_subscriptions_user_status ON subscriptions (user_id, status);

-- ---------------------------------------------------------------------------
-- Notifications and audit
-- ---------------------------------------------------------------------------
CREATE TABLE device_tokens (
    id         uuid PRIMARY KEY,
    user_id    uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token      varchar(512) NOT NULL UNIQUE,
    platform   varchar(20)  NOT NULL DEFAULT 'ANDROID',
    created_at timestamptz  NOT NULL DEFAULT now()
);

CREATE TABLE audit_logs (
    id         bigserial PRIMARY KEY,
    actor_id   uuid,
    action     varchar(60)  NOT NULL,
    target     varchar(100),
    metadata   jsonb,
    created_at timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX ix_audit_actor_created ON audit_logs (actor_id, created_at);
